def s(c):
    d = sp[c]; q = d['seq']
    ok_sync = sum(1 for b in q for t in b['pmTxs'] for f in t['frames'] if f == 'sync')
    fo = sum(1 for b in q for j, t in enumerate(b['pmTxs']) if (t['failedUnderUnlock'] or t['status'] == 0) and any(u['status'] == 1 and 'unlock' in u['frames'] for u in b['pmTxs'][j + 1:]))
    ex = [(b['block'], t['tx']) for b in q for t in b['pmTxs'] if (t['firstSettleValue'] or 0) > 0 and t['status'] == 1][:3]
    return dict(blocks=d['blocksTraced'], first=q[0]['block'], last=q[-1]['block'], txs=d['txsInTracedBlocks'], pm=d['pmTxs'], sync=ok_sync,
                open=len(d['txsLeavingErc20SyncOpen']), pairs=len(d['pairs']), native=d['laterNativeSettleBeforeSyncTxs'], fo=fo,
                multi=d['blocksWith2PlusPmTxs'], mism=len(d['mismatches']), cv=d['clientVersionBefore'], cva=d['clientVersionAfter'], ex=ex, t4=len(d['task4Blocks']))


S = {c: s(c) for c in sp}


def t1(c, name, how):
    x = S[c]
    exs = '; '.join(f'block {b} tx {h}' for b, h in x['ex'])
    return (f"{name}: {how} {x['blocks']} blocks with PoolManager logs, {x['first']} to {x['last']}, {x['txs']} transactions, {x['pm']} that reach the PoolManager, "
            f"{x['sync']} sync frames that did not fail. Transactions that succeed and end with an ERC-20 sync open: {x['open']}. Pairs (such a transaction followed in the "
            f"same block by a PoolManager transaction whose first settle precedes its own sync): {x['pairs']}. {x['native']} transactions settle native value before any sync "
            f"(examples {exs}), and none has an earlier open sync in its block to stand on. Receipts of the producer equal the traced execution in status, gas used and logs "
            f"for all {x['pm']} ({x['mism']} differences). Client versions before and after: {x['cv']} / {x['cva']}.")


